import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        Map<String, Integer> soni = new LinkedHashMap<>();
        for (int i = 0; i < n; i++) {
            String ip = in.next();
            soni.merge(ip, 1, Integer::sum);
        }
        String eng = "";
        int max = -1;
        for (Map.Entry<String, Integer> e : soni.entrySet()) {
            if (e.getValue() >= max) {
                max = e.getValue();
                eng = e.getKey();
            }
        }
        System.out.println(eng + ": " + max);
    }
}

