#include <string>
using namespace std;

int main() {
    int n;
    cin >> n;
    map<string, int> soni;
    for (int i = 0; i < n; i++) {
        string ip;
        cin >> ip;
        soni[ip]++;
    }
    string eng = soni.begin()->first;
    for (const auto& x : soni) {
        if (x.second >= soni[eng]) eng = x.first;
    }
    cout << eng << ": " << soni[eng] << endl;
    return 0;
}

