#include <iostream>
#include <map>
#include <string>
#include <vector>
using namespace std;

int main() {
    int n;
    cin >> n;
    vector<string> tartib;
    map<string, int> soni;
    for (int i = 0; i < n; i++) {
        string ip;
        cin >> ip;
        if (!soni.count(ip)) tartib.push_back(ip);
        soni[ip]++;
    }
    string eng = tartib[0];
    for (const string& ip : tartib) {
        if (soni[ip] > soni[eng]) eng = ip;
    }
    cout << eng << ": " << soni[eng] << endl;
    return 0;
}
